// ***************
// Filename: symbol_overlay_top.sv
// Author: FPGA Cores 4 U
// Description: symbol_overlay with its AXI4-Lite register interface, the
//   block designs and testbenches instantiate: the register map
//   symbol_overlay_regs (u_regs, src/include/symbol_overlay_regs.sv, ID
//   "SOVL", VERSION and DATE at 0x00-0x08, the registers from 0x10) and the
//   logic symbol_overlay (u_core, src/symbol_overlay.sv), joined by the
//   register interface symbol_overlay_regs_if (u_regs_if). Generated by
//   ip/scripts/regmap_gen.py from symbol_overlay_regs.json and the ports of
//   symbol_overlay: regenerate after changing either. Clock - clk. Reset -
//   synchronous active low rst_n.
// Date: 2026-10-16
module symbol_overlay_top #(
  parameter int NOBJ = 4,
  parameter int NTXT = 4,
  parameter int CW = 16
) (
  input  logic clk,
  input  logic rst_n,
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 10
  axil_if.slave s_axil,
  // s_axis: axis_if.slave (ip/shared/src/interfaces/axis_if.sv), DATA_W = 24
  axis_if.slave s_axis,
  // m_axis: axis_if.master (ip/shared/src/interfaces/axis_if.sv), DATA_W = 24
  axis_if.master m_axis
);
  // register interface between the register map and the logic
  symbol_overlay_regs_if #(.NOBJ(NOBJ), .NTXT(NTXT)) u_regs_if ();

  symbol_overlay_regs #(
    .NOBJ(NOBJ),
    .NTXT(NTXT)
  ) u_regs (
    .clk,
    .rst_n,
    .s_axil(s_axil),
    .r(u_regs_if)
  );
  symbol_overlay #(
    .NOBJ(NOBJ),
    .NTXT(NTXT),
    .CW(CW)
  ) u_core (
    .clk,
    .rst_n,
    .s_axis,
    .m_axis,
    .regs(u_regs_if)
  );
endmodule
